plt.axhline(y=0, color='k', linestyle='-', linewidth=0.5)
plt.axvline(x=0, color='k', linestyle='-', linewidth=0.5)
plt.grid(True, alpha=0.3)
plt.xlabel('x')
plt.ylabel('y')
plt.title('Fonction sinus')
plt.legend()
plt.show()

print("Graphique généré avec succès!")`},{id:"4",title:"Dérivée numérique",description:"Calcule la dérivée d'une fonction par différence finie",language:"javascript",category:"Analyse",level:"Intermédiaire",code:`// Dérivée numérique par la méthode des différences finies
function derivee(f, x, h = 0.0001) {
    return (f(x + h) - f(x - h)) / (2 * h);
}

// Test avec f(x) = x²
function f(x) {
    return x * x;
}

console.log("f(x) = x²");
console.log("f'(2) ≈", derivee(f, 2));  // Devrait être 4
console.log("f'(3) ≈", derivee(f, 3));  // Devrait être 6

// Test avec f(x) = sin(x)
console.log("\\nf(x) = sin(x)");
